/* --- formules-geriatrie.js --- */
// Formules et calculs en gériatrie
const FORMULES_GERIATRIE = [
  { id: 'form-1', nom: 'DFG (CKD-EPI)', formule: 'DFG = 141 × min(Scr/κ, 1)^α × max(Scr/κ, 1)^(-1.209) × 0.993^Âge × 1.018 [si femme]', utilisation: 'Fonction rénale pour adapter les doses médicamenteuses', unites: 'mL/min/1.73m²', seuils: '> 90 normal · 60-89 légère · 30-59 modérée · 15-29 sévère · < 15 dialyse' },
  { id: 'form-2', nom: 'IMC', formule: 'IMC = Poids (kg) / Taille² (m²)', utilisation: 'État nutritionnel (alerte si < 21 chez sujet âgé)', unites: 'kg/m²', seuils: '< 18.5 dénutrition · 18.5-24.9 normal · 25-29.9 surpoids · ≥ 30 obésité' },
  { id: 'form-3', nom: 'Clairance créatinine (Cockcroft)', formule: 'ClCr = (140-Âge) × Poids / (0.814 × Créatinine) [× 0.85 si femme]', utilisation: 'Estimation DFG pour posologie (plus simple que CKD-EPI)', unites: 'mL/min', seuils: '< 30 : adapter doses · < 10 : dialyse' },
  { id: 'form-4', nom: 'Bilan hydrique', formule: 'Bilan = Entrées (IV + PO) - Sorties (urines + selles + drain + insensible)', utilisation: 'Surveillance hydratation, insuffisance rénale, déshydratation', unites: 'mL/24h', seuils: 'Bilan négatif = déshydratation · Positif = surcharge' },
  { id: 'form-5', nom: 'Besoin calorique', formule: 'BEE (Harris-Benedict) : H = 66.5 + 13.75×P + 5×T - 6.75×Âge · F = 655 + 9.56×P + 1.85×T - 4.68×Âge', utilisation: 'Calcul besoins nutritionnels. Multiplier par 1.2-1.5 si stress.', unites: 'kcal/j', seuils: '30 kcal/kg/j en gériatrie · 25 kcal/kg/j si obèse' },
  { id: 'form-6', nom: 'Besoin protéique', formule: 'Protéines = 1.0-1.2 g/kg/j (normal) · 1.2-1.5 g/kg/j (stress/dénutrition)', utilisation: 'Prévention sarcopénie et dénutrition', unites: 'g/kg/j', seuils: '< 0.8 = insuffisant · 1.0-1.2 = maintien · 1.2-1.5 = réparation' },
  { id: 'form-7', nom: 'Osmolarité plasmatique', formule: 'Osmo = 2×(Na + K) + Glycémie/18 + Urée/2.8', utilisation: 'Diagnostic hyponatrémie (dilution vs contraction)', unites: 'mOsm/kg', seuils: '< 280 hyponatrémie dilutionnelle · 280-300 normal · > 300 déshydratation' },
  { id: 'form-8', nom: 'Anion Gap', formule: 'AG = Na - (Cl + HCO3)', utilisation: 'Diagnostic acidose métabolique (gap élevé = acidose organique)', unites: 'mEq/L', seuils: '8-12 normal · > 12 = gap élevé (acidocétose, lactique, urémie)' },
  { id: 'form-9', nom: 'FRAX', formule: 'Score calculé en ligne (frax.shef.ac.uk) : âge, sexe, IMC, fracture, parent, tabac, corticoïdes, AR, ostéoporose, alcool', utilisation: 'Décision de traitement ostéoporose', unites: '% fractur à 10 ans', seuils: '> 3% fracture majeure ou > 20% hanche = traiter' },
  { id: 'form-10', nom: 'Score de Wells (EP)', formule: 'Clinique EP : 3 points · Autres : 1-1.5 points chacun. Total > 4 = probable', utilisation: 'Probabilité d\'embolie pulmonaire', unites: 'points', seuils: '< 4 faible probabilité · ≥ 4 haute probabilité' }
];


